1	/**
2	 * Wave 3 games — make RuneScape: Dragonwilds, Sunkenland, Abiotic Factor,
3	 * Core Keeper and Icarus orderable. Same Docker/OsTemplate pattern as Waves 1-2:
4	 * each is a community Docker image (wrapping SteamCMD, +Wine where the game's
5	 * dedicated-server build is Windows-only) installed by the OsTemplate.setupScript
6	 * in cloud-init. Researched 2026-08-31 against each game's official dedicated-
7	 * server docs / SteamDB — all five have real, currently-shipping dedicated
8	 * server support (none are P2P/lobby-only, unlike schedule1 which stays
9	 * unseeded — see lib/games.ts and lib/game-control.ts comments).
10	 *
11	 * Steam App IDs (dedicated server, NOT the game client):
12	 *   dragonwilds     4019830  (RuneScape: Dragonwilds Dedicated Server — native Linux)
13	 *   sunkenland      2667530  (Sunkenland Dedicated Server — Windows-only, Wine image)
14	 *   abioticfactor   2857200  (Abiotic Factor Dedicated Server — Windows-only, Wine image)
15	 *   corekeeper      1963720  (Core Keeper Dedicated Server — native Linux)
16	 *   icarus          2089300  (Icarus Dedicated Server — Windows-only, Wine image)
17	 *
18	 * Docker images picked to match publishers ALREADY trusted elsewhere in this
19	 * catalog where possible (same continuity as Waves 1-2 picking one community
20	 * image per game): indifferentbroccoli (already projectzomboid), melle2
21	 * (already conan), mornedhels (already enshrouded). Core Keeper and Abiotic
22	 * Factor use the most widely-referenced community images for their game
23	 * (escapingnetwork, Pleut) since no already-used publisher ships those.
24	 *
25	 * NOTE: static in-container placeholder passwords ("changeme12"/blank) — customers
26	 * change them post-deploy, matching every prior wave. Dragonwilds' OWNER_ID (the
27	 * server owner's Steam64 id, grants in-game admin) is a genuinely per-customer
28	 * value with no sane platform default — seeded as "0" (server boots fine without
29	 * it; only affects who can already issue admin commands) with a hint in
30	 * ADMIN_PASSWORD for the customer to set OWNER_ID post-deploy via SFTP.
31	 *
32	 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave3-games.ts   (idempotent)
33	 */
34	import { PrismaClient } from "@prisma/client";
35	
36	const db = new PrismaClient();
37	
38	type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };
39	
40	const TEMPLATES: Template[] = [
41	  {
42	    family: "dragonwilds", name: "RuneScape: Dragonwilds Server", minRamMB: 4096, minDiskGB: 20,
43	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dragonwilds && docker run -d --name dragonwilds --restart unless-stopped --stop-timeout 30 -p 7777:7777/udp -e OWNER_ID='0' -e ADMIN_PASSWORD='changeme12' -e SERVER_NAME='Nxeon' -e DEFAULT_PORT='7777' -e MAX_PLAYERS='6' -v /opt/dragonwilds:/home/steam/server-files indifferentbroccoli/runescape-dragonwilds-server-docker:latest`,
44	  },
45	  {
46	    family: "sunkenland", name: "Sunkenland Server", minRamMB: 4096, minDiskGB: 20,
47	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/sunkenland/Worlds /opt/sunkenland/game /opt/sunkenland/Steam && docker run -d --name sunkenland --restart unless-stopped -p 27015:27015/udp -p 27016:27016/udp -e GAME_WORLD_GUID='nxeon-world' -v /opt/sunkenland/Worlds:/sunkenland/Worlds -v /opt/sunkenland/game:/sunkenland/game -v /opt/sunkenland/Steam:/sunkenland/Steam melle2/sunkenland-ds:latest`,
48	  },
49	  {
50	    family: "abioticfactor", name: "Abiotic Factor Server", minRamMB: 6144, minDiskGB: 25,
51	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/abioticfactor/gamefiles /opt/abioticfactor/data && docker run -d --name abioticfactor --restart unless-stopped -p 7777:7777/udp -p 27015:27015/udp -e MaxServerPlayers='6' -e Port='7777' -e QueryPort='27015' -e ServerPassword='changeme12' -e SteamServerName='Nxeon' -e WorldSaveName='Cascade' -v /opt/abioticfactor/gamefiles:/server -v /opt/abioticfactor/data:/server/AbioticFactor/Saved ghcr.io/pleut/abiotic-factor-linux-docker:latest`,
52	  },
53	  {
54	    family: "corekeeper", name: "Core Keeper Server", minRamMB: 2048, minDiskGB: 15,
55	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/corekeeper/data /opt/corekeeper/files && docker run -d --name corekeeper --restart unless-stopped -p 27015:27015/udp -e WORLD_NAME='Nxeon Core Keeper' -e MAX_PLAYERS='8' -e SERVER_PORT='27015' -v /opt/corekeeper/data:/home/steam/core-keeper-data -v /opt/corekeeper/files:/home/steam/core-keeper-dedicated escaping/core-keeper-dedicated:latest`,
56	  },
57	  {
58	    family: "icarus", name: "Icarus Server", minRamMB: 6144, minDiskGB: 30,
59	    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/icarus/data /opt/icarus/game && docker run -d --name icarus --hostname icarus --restart unless-stopped --stop-timeout 90 -p 17777:17777/udp -p 27015:27015/udp -e SERVER_NAME='Nxeon' -e SERVER_PASSWORD='' -e SERVER_ADMIN_PASSWORD='changeme12' -e SERVER_PORT='17777' -e SERVER_QUERYPORT='27015' -e PUID='4711' -e PGID='4711' -v /opt/icarus/data:/home/icarus/drive_c/icarus -v /opt/icarus/game:/opt/icarus mornedhels/icarus-server:latest`,
60	  },
61	];
62	
63	type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };
64	
65	const TIERS: TierSpec[] = [
66	  // Dragonwilds — hard-capped at 6 players; official spec is 2 GB + 1 GB/player.
67	  { gameFamily: "dragonwilds", name: "Dragonwilds — 4 GB / 3 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 3, priceCents: 899 },
68	  { gameFamily: "dragonwilds", name: "Dragonwilds — 6 GB / 5 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 5, priceCents: 1299, featured: true },
69	  { gameFamily: "dragonwilds", name: "Dragonwilds — 8 GB / 6 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 6, priceCents: 1699 },
70	
71	  // Sunkenland — small-party raft/island survival, similar scale to Valheim/Enshrouded.
72	  { gameFamily: "sunkenland", name: "Sunkenland — 4 GB / 4 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 4, priceCents: 899 },
73	  { gameFamily: "sunkenland", name: "Sunkenland — 6 GB / 8 players", ramMB: 6144, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1399, featured: true },
74	  { gameFamily: "sunkenland", name: "Sunkenland — 8 GB / 10 players", ramMB: 8192, cpuCores: 4, diskGB: 40, slots: 10, priceCents: 1899 },
75	
76	  // Abiotic Factor — Wine-based like Enshrouded, small co-op teams.
77	  { gameFamily: "abioticfactor", name: "Abiotic Factor — 6 GB / 4 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 4, priceCents: 1199 },
78	  { gameFamily: "abioticfactor", name: "Abiotic Factor — 8 GB / 6 players", ramMB: 8192, cpuCores: 3, diskGB: 35, slots: 6, priceCents: 1699, featured: true },
79	  { gameFamily: "abioticfactor", name: "Abiotic Factor — 12 GB / 8 players", ramMB: 12288, cpuCores: 4, diskGB: 45, slots: 8, priceCents: 2299 },
80	
81	  // Core Keeper — lightweight 2D sandbox, native Linux; official cap is 8 players.
82	  { gameFamily: "corekeeper", name: "Core Keeper — 2 GB / 6 players", ramMB: 2048, cpuCores: 1, diskGB: 15, slots: 6, priceCents: 499 },
83	  { gameFamily: "corekeeper", name: "Core Keeper — 4 GB / 8 players", ramMB: 4096, cpuCores: 2, diskGB: 25, slots: 8, priceCents: 799, featured: true },
84	  { gameFamily: "corekeeper", name: "Core Keeper — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 35, slots: 8, priceCents: 1199 },
85	
86	  // Icarus — Wine-based like Enshrouded, procedural-planet co-op prospects.
87	  { gameFamily: "icarus", name: "Icarus — 6 GB / 4 players", ramMB: 6144, cpuCores: 2, diskGB: 30, slots: 4, priceCents: 1299 },
88	  { gameFamily: "icarus", name: "Icarus — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 40, slots: 8, priceCents: 1899, featured: true },
89	  { gameFamily: "icarus", name: "Icarus — 12 GB / 8 players", ramMB: 12288, cpuCores: 4, diskGB: 50, slots: 8, priceCents: 2499 },
90	];
91	
92	async function main() {
93	  const templateIdByFamily = new Map<string, string>();
94	  let sort = 50;
95	  for (const t of TEMPLATES) {
96	    const os = await db.osTemplate.upsert({
97	      where: { slug: t.family },
98	      create: {
99	        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
100	        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
101	        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
102	      },
103	      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
104	    });
105	    templateIdByFamily.set(t.family, os.id);
106	    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
107	  }
108	
109	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
110	  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
111	  const largest = plans[plans.length - 1];
112	
113	  let created = 0, updated = 0;
114	  const sortByGame = new Map<string, number>();
115	  for (const spec of TIERS) {
116	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
117	    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
118	    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
119	    sortByGame.set(spec.gameFamily, sortOrder + 1);
120	    const data = {
121	      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
122	      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
123	      featured: spec.featured ?? false, active: true, sortOrder,
124	    };
125	    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
126	    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
127	    else { await db.gamePlan.create({ data }); created++; }
128	    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
129	  }
130	  console.log(`\nWave 3: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
131	}
132	
133	main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
134
